#define TAU 6.28318530718
#define LOOP_SECONDS 16.0

// Pocket DoJa: Azure Flow
// Original procedural shader with a seamless 16-second loop.

float gaussian(float x, float width)
{
    float v = x / width;
    return exp(-v * v);
}

void addRibbon(
    inout vec3 color,
    float distanceToCurve,
    float width,
    vec3 tint
) {
    float d = distanceToCurve;

    // Soft blue-grey shadow beneath each flowing layer.
    float shadow = gaussian(
        d + width * 0.78,
        width * 0.30
    );

    color *= 1.0 - 0.045 * shadow;

    // Feathered translucent ribbon.
    float body = 1.0 - smoothstep(
        width,
        width + 0.025,
        abs(d)
    );

    color = mix(color, tint, body * 0.58);

    // Cool, delicate highlight along the ribbon.
    float highlight = gaussian(
        d - width * 0.48,
        width * 0.13
    );

    color = mix(
        color,
        vec3(1.0, 1.0, 1.0),
        highlight * 0.36
    );
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;

    // Keep the wave proportions consistent on different screens.
    vec2 p = (fragCoord - 0.5 * iResolution.xy)
           / iResolution.y;

    // Periodic phase: returns to its starting point every 16 seconds.
    float phase = TAU * fract(iTime / LOOP_SECONDS);
    float x = uv.x * TAU;

    // Icy-white background with a subtle azure gradient.
    vec3 color = mix(
        vec3(0.80, 0.89, 0.98),
        vec3(0.985, 0.995, 1.0),
        smoothstep(-0.48, 0.48, p.y)
    );

    // Three original flowing wave curves.
    float waveA =
        -0.235
        + 0.063 * sin(x * 0.64 + phase)
        + 0.018 * sin(x * 1.28 - 2.0 * phase);

    float waveB =
        -0.025
        + 0.066 * sin(x * 0.51 - phase + 1.35)
        + 0.018 * sin(x * 1.02 + 2.0 * phase);

    float waveC =
         0.185
        + 0.052 * sin(x * 0.59 + phase + 2.2)
        + 0.015 * sin(x * 1.18 - 2.0 * phase);

    // Lower ribbon: soft powder blue.
    addRibbon(
        color,
        p.y - waveA,
        0.082,
        vec3(0.57, 0.75, 0.94)
    );

    // Middle ribbon: pale sky blue.
    addRibbon(
        color,
        p.y - waveB,
        0.090,
        vec3(0.72, 0.86, 0.98)
    );

    // Upper ribbon: delicate azure.
    addRibbon(
        color,
        p.y - waveC,
        0.078,
        vec3(0.48, 0.70, 0.92)
    );

    // Gentle edge falloff for a polished interface background.
    float edge = smoothstep(
        1.15, 0.15,
        length(vec2(p.x * 0.60, p.y * 0.85))
    );

    color = mix(color, color * 0.985, edge * 0.22);

    fragColor = vec4(color, 1.0);
}
